platformStatus.query:
query platformStatus {
  platformStatus {
    ...PlatformStatusFields
  }
}

fragment PlatformStatusFields on PlatformStatus {
  isStable
  incident {
    ...IncidentFields
  }
  maintenance {
    ...MaintenanceFields
  }
}

fragment IncidentFields on Incident {
  id
  message
  status
  url
}

fragment MaintenanceFields on Maintenance {
  id
  message
  status
  url
  start
}

me.query:
query me {
  me {
    ...UserFields
  }
}

fragment UserFields on User {
  id
  email
  name
  username
  avatar
  profile {
    ...UserProfileFields
  }
  isAdmin
  isConductor
  createdAt
  flags
  featureFlags
  agreedFairUse
  termsAgreedOn
  isVerified
  banReason
  providerAuths {
    edges {
      node {
        id
        provider
        isAuthEnabled
        metadata
        email
      }
    }
  }
  workspaces {
    ...WorkspaceFields
  }
}

fragment UserProfileFields on UserProfile {
  bio
  website
  isPublic
}

fragment WorkspaceFields on Workspace {
  id
  plan
  subscriptionPlanLimit
  name
  avatar
  customer {
    id
    state
    isTrialing
    spendCommitment {
      features
      minSpendAmountCents
    }
  }
  hasSAML
  hasHipaaBAA
  has2FAEnforcement
  hasAutomaticDiagnosis
  redactedDueTo2FAPending
  discordRole
  banReason
  restriction {
    id
    type
    reason
    allowsUserAppeal
    activeAppeal {
      id
      type
      status
      createdAt
      threadId
    }
    workspaceAppeal {
      id
      status
      createdAt
      submittedBy {
        id
        email
        name
      }
    }
    viewerAppeal {
      id
      type
      status
      createdAt
    }
  }
  slackChannelId
  preferredRegion
  createdAt
  currentSessionHasAccess
  viewerRole
  projects {
    edges {
      node {
        id
        name
        isPublic
        deletedAt
      }
    }
  }
}

workspace.query:
query workspace($workspaceId: String!) {
  workspace(workspaceId: $workspaceId) {
    agentsConfigEnabled
    customer {
      ...CustomerFields
    }
  }
}

fragment CustomerFields on Customer {
  id
  state
  isUsageSubscriber
  isTrialing
  stripeCustomerId
  isPrepaying
  hasExhaustedFreePlan
  usageLimit {
    ...UsageLimitFields
  }
  billingPeriod {
    start
    end
  }
}

fragment UsageLimitFields on UsageLimit {
  softLimit
  hardLimit
}

freePlanBalance.query:
query freePlanBalance($workspaceId: String!) {
  workspace(workspaceId: $workspaceId) {
    customer {
      ...FreePlanBalanceFields
    }
  }
}

fragment FreePlanBalanceFields on Customer {
  remainingUsageCreditBalance
  trialDaysRemaining
  volumeDeletionScheduledAt
}

